mapper.update:
UPDATE sys_menu
SET status = #{status},
    updated_at = #{updatedAt}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM sys_menu
WHERE menu_key = #{menuKey}
AND id != #{excludeId}

SELECT COUNT(*)
FROM sys_menu
WHERE route_path = #{routePath}
AND id != #{excludeId}

SELECT FROM sys_menu WHERE id IN
#{id}
ORDER BY parent_id, sort_no, id
